sections.content:
table inet fw {
 chain input {
  type filter hook input \
    priority 0; policy drop;
  ct state established,related accept
  ct state invalid drop
  iif "lo" accept
  ip saddr 10.10.20.0/24 \
    tcp dport 22 accept
 }
 chain forward {
  type filter hook forward \
    priority 0; policy drop;
  ct state established,related accept
  iifname "lan" oifname "wan" accept
  iifname "wan" oifname "dmz" \
    ip daddr 10.10.200.10 \
    tcp dport 443 accept
 }
}

table ip nat {
 chain pre {
  type nat hook prerouting \
    priority dstnat;
  iifname "wan" tcp dport 443 \
    dnat to 10.10.200.10
 }
 chain post {
  type nat hook postrouting \
    priority srcnat;
  oifname "wan" masquerade
 }
}

